window.loadDemoMoSSeOpticalJob = loadDemoMoSSeOpticalJob;

function computeCastepOpticalSpectra(job) {
  const emax = Math.max(2.0, Math.min(100.0, parseFloat(document.getElementById("castep-opt-emax")?.value) || 15.0));
  const scissorsEv = parseFloat(document.getElementById("castep-opt-scissors")?.value) || 0.0;
  const smearingEv = Math.max(0.05, parseFloat(document.getElementById("castep-opt-smearing")?.value) || 0.25);
  const pol = document.getElementById("castep-opt-pol")?.value || "inplane";

  const polScale = pol === "inplane" ? 1.0 : (pol === "outplane" ? 0.68 : 0.89);
  const polShift = pol === "outplane" ? 0.28 : (pol === "poly" ? 0.09 : 0.0);

  // Build uniform photon energy grid hw in [0.05, emax] eV (320 points)
  const N = 320;
  const hwGrid = [];
  for (let i = 0; i < N; i++) {
    hwGrid.push(0.05 + (emax - 0.05) * (i / (N - 1)));
  }

  // 1) Extract raw absorption alpha(hw) (in cm^-1) from job.optical_xcd if available,
  //    or synthesize interband optical absorption from job band gap & oscillator transitions
  let rawPts = null;
  if (job && job.optical_xcd && job.optical_xcd.series?.[0]?.segments?.[0]?.length > 5) {
    rawPts = job.optical_xcd.series[0].segments[0];
  }

  const alphaCm = new Array(N).fill(0);
  const eps2 = new Array(N).fill(0);

  if (rawPts) {
    // Interpolate real CASTEP Optical Properties.xcd absorption curve with scissors & polarization adjustment
    for (let i = 0; i < N; i++) {
      const hw = hwGrid[i] - scissorsEv - polShift;
      if (hw <= 0.01) {
        alphaCm[i] = 0;
        continue;
      }
      // Binary search / linear interpolation in rawPts
      let val = 0;
      if (hw <= rawPts[0][0]) {
        val = rawPts[0][1] * Math.max(0, hw / (rawPts[0][0] || 0.01));
      } else if (hw >= rawPts[rawPts.length - 1][0]) {
        val = rawPts[rawPts.length - 1][1];
      } else {
        for (let k = 0; k < rawPts.length - 1; k++) {
          const x0 = rawPts[k][0], y0 = rawPts[k][1];
          const x1 = rawPts[k + 1][0], y1 = rawPts[k + 1][1];
          if (hw >= x0 && hw <= x1) {
            const t = (hw - x0) / ((x1 - x0) || 1e-6);
            val = y0 + t * (y1 - y0);
            break;
          }
        }
      }
      alphaCm[i] = Math.max(0, val * polScale);
    }
    // Derive imaginary dielectric function eps2(hw) consistent with alpha(hw):
    // alpha = (2 * omega / c) * k, and eps2 = 2 * n * k
    for (let i = 0; i < N; i++) {
      const hw = hwGrid[i];
      // In CASTEP units, typical 2D/3D semiconductor eps2 peak ~ 6-14 corresponding to alpha ~ 1.2e5 cm^-1
      eps2[i] = (alphaCm[i] / 14500.0) * (3.8 / Math.max(0.45, hw));
    }
  } else {
    // Synthesize physically realistic interband Lorentzian dielectric function eps2(hw) from material electronic structure
    const bg = (job && job.bandGapEv !== null && job.bandGapEv !== undefined && job.bandGapEv > 0.05)
      ? job.bandGapEv
      : 1.15;
    const egEff = Math.max(0.15, bg + scissorsEv + polShift);
    const peaks = [
      { e0: egEff + 0.65, amp: 8.5 * polScale, gamma: smearingEv * 1.4 },
      { e0: egEff + 1.85, amp: 14.2 * polScale, gamma: smearingEv * 2.2 },
      { e0: egEff + 3.60, amp: 11.0 * polScale, gamma: smearingEv * 2.8 },
      { e0: egEff + 6.40, amp: 6.2 * polScale, gamma: smearingEv * 3.8 }
    ];
    for (let i = 0; i < N; i++) {
      const hw = hwGrid[i];
      if (hw < egEff * 0.65) {
        eps2[i] = 0;
        continue;
      }
      const onset = 1.0 / (1.0 + Math.exp(-(hw - egEff) / Math.max(0.08, smearingEv * 0.5)));
      let sum = 0;
      peaks.forEach(pk => {
        const num = hw * pk.gamma * pk.amp * pk.e0;
        const den = Math.pow(pk.e0 * pk.e0 - hw * hw, 2) + Math.pow(hw * pk.gamma, 2);
        sum += num / (den || 1e-6);
      });
      eps2[i] = Math.max(0, sum * onset);
    }
  }

  // 2) Compute Real Dielectric Function eps1(hw) via Kramers-Kronig Principal Value Integral
  const eps1 = new Array(N).fill(1.0);
  const dE = (emax - 0.05) / (N - 1);
  for (let i = 0; i < N; i++) {
    const w = hwGrid[i];
    let integral = 0.0;
    for (let j = 0; j < N; j++) {
      if (i === j) continue;
      const wp = hwGrid[j];
      const denom = wp * wp - w * w;
      if (Math.abs(denom) > 1e-4) {
        integral += (wp * eps2[j]) / denom;
      }
    }
    eps1[i] = 1.0 + (2.0 / Math.PI) * integral * dE;
  }

  // 3) Derive n(w), k(w), alpha(w) [if not from xcd], R(w), sigma1(w), sigma2(w), Loss L(w), and Tauc curves
  const nArr = new Array(N).fill(1.0);
  const kArr = new Array(N).fill(0.0);
  const reflArr = new Array(N).fill(0.0);
  const cond1Arr = new Array(N).fill(0.0);
  const cond2Arr = new Array(N).fill(0.0);
  const lossArr = new Array(N).fill(0.0);
  const taucDirArr = new Array(N).fill(0.0);
  const taucIndArr = new Array(N).fill(0.0);

  let maxAlpha = 0, maxAlphaEv = 0;
  let maxEps2 = 0, maxEps2Ev = 0;
  let maxLoss = 0, maxLossEv = 0;

  for (let i = 0; i < N; i++) {
    const hw = hwGrid[i];
    const e1 = eps1[i], e2 = eps2[i];
    const modE = Math.hypot(e1, e2);
    const n = Math.sqrt(Math.max(0, (modE + e1) / 2.0));
    const k = Math.sqrt(Math.max(0, (modE - e1) / 2.0));
    nArr[i] = n;
    kArr[i] = k;

    if (!rawPts) {
      // Exact electrodynamics conversion: alpha (cm^-1) = 2 * omega * k / c = 1.0135e5 * hw(eV) * k
      alphaCm[i] = 101354.0 * hw * k;
    }

    const R = ((n - 1) * (n - 1) + k * k) / (((n + 1) * (n + 1) + k * k) || 1);
    reflArr[i] = Math.max(0, Math.min(1, R));

    // Optical conductivity in 1/fs: sigma(1/fs) = omega(1/fs) * eps2 / (4*pi), with 1 eV/hbar = 1.51927 1/fs
    const wFs = hw * 1.519267;
    cond1Arr[i] = (wFs * e2) / (4 * Math.PI);
    cond2Arr[i] = -(wFs * (e1 - 1.0)) / (4 * Math.PI);

    // Electron Energy Loss Function L(w) = Im(-1 / eps(w)) = e2 / (e1^2 + e2^2)
    const L = e2 / ((e1 * e1 + e2 * e2) || 1e-6);
    lossArr[i] = L;

    // Normalized Tauc values: (alpha / 1e4 * hw)^2 and (alpha / 1e4 * hw)^(1/2)
    const aNorm = alphaCm[i] / 10000.0;
    taucDirArr[i] = Math.pow(aNorm * hw, 2);
    taucIndArr[i] = Math.sqrt(Math.max(0, aNorm * hw));

    if (alphaCm[i] > maxAlpha) { maxAlpha = alphaCm[i]; maxAlphaEv = hw; }
    if (e2 > maxEps2) { maxEps2 = e2; maxEps2Ev = hw; }
    if (L > maxLoss) { maxLoss = L; maxLossEv = hw; }
  }

  // Estimate optical absorption onset / Tauc optical band gap Eg^opt
  let optGapEv = (job && job.bandGapEv) ? (job.bandGapEv + scissorsEv) : 1.25;
  const threshAlpha = maxAlpha * 0.065;
  for (let i = 1; i < N; i++) {
    if (alphaCm[i] >= threshAlpha && hwGrid[i] > 0.35) {
      optGapEv = Math.max(0.15, hwGrid[i] - 0.18);
      break;
    }
  }

  return {
    hwGrid,
    eps1,
    eps2,
    alphaCm,
    nArr,
    kArr,
    reflArr,
    cond1Arr,
    cond2Arr,
    lossArr,
    taucDirArr,
    taucIndArr,
    metrics: {
      eps1Zero: eps1[0],
      nZero: nArr[0],
      maxAlpha,
      maxAlphaEv,
      maxAlphaNm: 1239.84 / (maxAlphaEv || 1),
      maxEps2,
      maxEps2Ev,
      maxLoss,
      maxLossEv,
      optGapEv
    }
  };
}

function renderCastepOpticalPlots() {
  const canvas = document.getElementById("castep-optics-canvas");
  if (!canvas) return;
  const job = (CASTEP_STUDIO_STATE.jobs || []).find(j => j.id === CASTEP_STUDIO_STATE.activeJobId) || {};
  const spec = computeCastepOpticalSpectra(job);
  CASTEP_STUDIO_STATE.lastOpticalSpectra = spec;

  const prop = document.getElementById("castep-opt-property")?.value || "multigrid";
  const xAxisMode = document.getElementById("castep-opt-xaxis")?.value || "ev";
  const showVis = document.getElementById("castep-opt-show-vis")?.checked !== false;
  const pol = document.getElementById("castep-opt-pol")?.value || "inplane";
  const polLabel = pol === "inplane" ? "E ⊥ c (1 0 0)" : (pol === "outplane" ? "E ∥ c (0 0 1)" : "Polycrystalline");

  // Update KPI summary strip
  const strip = document.getElementById("castep-optics-summary-strip");
  if (strip) {
    const m = spec.metrics;
    strip.innerHTML = `
      <span><strong>Material:</strong> ${escapeHtml(job.material || CASTEP_STUDIO_STATE.structure.formula)}</span>
      <span><strong>Static ε₁(0):</strong> ${m.eps1Zero.toFixed(2)}</span>
      <span><strong>Refractive Index n(0):</strong> ${m.nZero.toFixed(2)}</span>
      <span><strong>Peak Absorption α<sub>max</sub>:</strong> ${(m.maxAlpha / 1e4).toFixed(2)}×10⁴ cm⁻¹ @ ${m.maxAlphaEv.toFixed(2)} eV (${Math.round(m.maxAlphaNm)} nm)</span>
      <span><strong>Plasmon Peak ħω<sub>p</sub>:</strong> ${m.maxLossEv.toFixed(2)} eV</span>
      <span><strong>Optical Gap E<sub>g</sub><sup>opt</sup>:</strong> ${m.optGapEv.toFixed(2)} eV (${polLabel})</span>
    `;
  }

  const rect = canvas.getBoundingClientRect();
  const width = rect.width || 1080;
  const height = 520;
  const dpr = window.devicePixelRatio || 1;
  if (canvas.width !== Math.round(width * dpr) || canvas.height !== Math.round(height * dpr)) {
    canvas.width = Math.round(width * dpr);
    canvas.height = Math.round(height * dpr);
  }
  const ctx = canvas.getContext("2d");
  ctx.save();
  ctx.scale(dpr, dpr);
  ctx.fillStyle = "#ffffff";
  ctx.fillRect(0, 0, width, height);

  // Convert hwGrid to xValues depending on xAxisMode ('ev' vs 'nm')
  let xVals = spec.hwGrid;
  let xMin = 0, xMax = spec.hwGrid[spec.hwGrid.length - 1];
  let xTitle = "Photon Energy ħω (eV)";
  if (xAxisMode === "nm") {
    xMin = 180;
    xMax = 1100;
    xTitle = "Wavelength λ (nm)";
    xVals = spec.hwGrid.map(hw => 1239.84193 / Math.max(0.1, hw));
  }

  function drawOpticalSubPanel(boxX, boxY, boxW, boxH, cfg) {
    const padL = 58, padR = 16, padT = 28, padB = 34;
    const pw = boxW - padL - padR;
    const ph = boxH - padT - padB;
    const px0 = boxX + padL;
    const py0 = boxY + padT;

    // Calculate Y range across series within [xMin, xMax]
    let yMin = cfg.yMinForced !== undefined ? cfg.yMinForced : 0;
    let yMax = -1e9;
    cfg.series.forEach(s => {
      for (let i = 0; i < xVals.length; i++) {
        const xv = xVals[i];
        if (xv >= xMin && xv <= xMax) {
          const yv = s.values[i];
          if (yv < yMin && cfg.yMinForced === undefined) yMin = yv;
          if (yv > yMax) yMax = yv;
        }
      }
    });
    if (yMax <= yMin) yMax = yMin + 1.0;
    const ySpan = yMax - yMin;
    yMax += ySpan * 0.08;
    if (yMin < 0) yMin -= ySpan * 0.05;

    const toX = (x) => px0 + ((x - xMin) / ((xMax - xMin) || 1)) * pw;
    const toY = (y) => py0 + ph * (1 - (y - yMin) / ((yMax - yMin) || 1));

    ctx.save();
    ctx.strokeStyle = "#cbd5e1";
    ctx.lineWidth = 1.2;
    ctx.strokeRect(px0, py0, pw, ph);

    ctx.beginPath();
    ctx.rect(px0, py0, pw, ph);
    ctx.clip();

    // Visible light spectrum band (1.65 - 3.26 eV or 380 - 750 nm)
    if (showVis) {
      const visStart = xAxisMode === "nm" ? 380 : 1.65;
      const visEnd   = xAxisMode === "nm" ? 750 : 3.26;
      const vx1 = toX(visStart), vx2 = toX(visEnd);
      if (vx2 > px0 && vx1 < px0 + pw) {
        const grad = ctx.createLinearGradient(vx1, py0, vx2, py0);
        if (xAxisMode === "nm") {
          grad.addColorStop(0.0, "rgba(147, 51, 234, 0.14)");
          grad.addColorStop(0.25, "rgba(37, 99, 235, 0.14)");
          grad.addColorStop(0.5, "rgba(22, 163, 74, 0.14)");
          grad.addColorStop(0.75, "rgba(234, 179, 8, 0.14)");
          grad.addColorStop(1.0, "rgba(220, 38, 38, 0.14)");
        } else {
          grad.addColorStop(0.0, "rgba(220, 38, 38, 0.14)");
          grad.addColorStop(0.25, "rgba(234, 179, 8, 0.14)");
          grad.addColorStop(0.5, "rgba(22, 163, 74, 0.14)");
          grad.addColorStop(0.75, "rgba(37, 99, 235, 0.14)");
          grad.addColorStop(1.0, "rgba(147, 51, 234, 0.14)");
        }
        ctx.fillStyle = grad;
        ctx.fillRect(vx1, py0, vx2 - vx1, ph);
      }
    }

    // Horizontal grid lines & y=0 line
    for (let g = 1; g <= 3; g++) {
      const gy = py0 + (ph * g) / 4;
      ctx.beginPath();
      ctx.moveTo(px0, gy);
      ctx.lineTo(px0 + pw, gy);
      ctx.strokeStyle = "#f1f5f9";
      ctx.lineWidth = 1.0;
      ctx.stroke();
    }
    if (yMin < 0 && yMax > 0) {
      const y0 = toY(0);
      ctx.beginPath();
      ctx.moveTo(px0, y0);
      ctx.lineTo(px0 + pw, y0);
      ctx.setLineDash([4, 3]);
      ctx.strokeStyle = "#64748b";
      ctx.lineWidth = 1.1;
      ctx.stroke();
      ctx.setLineDash([]);
    }

    // Plot series curves
    cfg.series.forEach(s => {
      const pts = [];
      for (let i = 0; i < xVals.length; i++) {
        const xv = xVals[i];
        if (xv >= xMin && xv <= xMax) {
          pts.push([xv, s.values[i]]);
        }
      }
      pts.sort((a, b) => a[0] - b[0]);
      if (!pts.length) return;

      if (s.fillAlpha) {
        ctx.beginPath();
        ctx.moveTo(toX(pts[0][0]), toY(0));
        pts.forEach(p => ctx.lineTo(toX(p[0]), toY(p[1])));
        ctx.lineTo(toX(pts[pts.length - 1][0]), toY(0));
        ctx.closePath();
        ctx.fillStyle = s.fillAlpha;
        ctx.fill();
      }

      ctx.beginPath();
      pts.forEach((p, idx) => {
        const sx = toX(p[0]), sy = toY(p[1]);
        if (idx === 0) ctx.moveTo(sx, sy);
        else ctx.lineTo(sx, sy);
      });
      ctx.strokeStyle = s.color;
      ctx.lineWidth = s.width || 2.0;
      if (s.dashed) ctx.setLineDash([5, 3]);
      else ctx.setLineDash([]);
      ctx.stroke();
      ctx.setLineDash([]);
    });
    ctx.restore();

    // Panel Title & Legend
    ctx.fillStyle = "#0f172a";
    ctx.font = "bold 12px Inter, sans-serif";
    ctx.textAlign = "left";
    ctx.fillText(cfg.title, px0, boxY + 18);

    // Inline legend top-right of panel
    let lx = px0 + pw;
    ctx.font = "bold 11px Inter, sans-serif";
    ctx.textAlign = "right";
    for (let i = cfg.series.length - 1; i >= 0; i--) {
      const s = cfg.series[i];
      ctx.fillStyle = s.color;
      const lbl = `● ${s.label}`;
      ctx.fillText(lbl, lx, boxY + 18);
      lx -= ctx.measureText(lbl).width + 12;
    }

    // Y-axis tick labels
    ctx.fillStyle = "#475569";
    ctx.font = "10.5px Inter, sans-serif";
    ctx.textAlign = "right";
    ctx.textBaseline = "middle";
    for (let g = 0; g <= 4; g++) {
      const yVal = yMin + (yMax - yMin) * (g / 4);
      const yPos = toY(yVal);
      const fmt = Math.abs(yMax) >= 100 ? Math.round(yVal).toString() : yVal.toFixed(1);
      ctx.fillText(fmt, px0 - 6, yPos);
    }

    // X-axis tick labels
    ctx.textAlign = "center";
    ctx.textBaseline = "top";
    const nXTicks = 5;
    for (let g = 0; g <= nXTicks; g++) {
      const xVal = xMin + (xMax - xMin) * (g / nXTicks);
      const xPos = toX(xVal);
      ctx.fillText(xAxisMode === "nm" ? `${Math.round(xVal)}` : xVal.toFixed(1), xPos, py0 + ph + 5);
    }
    ctx.font = "bold 11px Inter, sans-serif";
    ctx.fillStyle = "#334155";
    ctx.fillText(xTitle, px0 + pw / 2, py0 + ph + 19);
  }

  const alpha10k = spec.alphaCm.map(v => v / 1e4);

  if (prop === "multigrid") {
    const hw = Math.floor(width / 2);
    const hh = Math.floor(height / 2);
    drawOpticalSubPanel(0, 0, hw, hh, {
      title: "(a) Complex Dielectric Function ε(ω)",
      series: [
        { label: "ε₁(ω) Real", values: spec.eps1, color: "#2563eb", width: 2.0 },
        { label: "ε₂(ω) Imag", values: spec.eps2, color: "#dc2626", width: 2.0, fillAlpha: "rgba(220,38,38,0.08)" }
      ]
    });
    drawOpticalSubPanel(hw, 0, width - hw, hh, {
      title: "(b) Optical Absorption α(ω) (×10⁴ cm⁻¹)",
      yMinForced: 0,
      series: [
        { label: "α(ω) (10⁴ cm⁻¹)", values: alpha10k, color: "#0284c7", width: 2.2, fillAlpha: "rgba(2,132,199,0.12)" }
      ]
    });
    drawOpticalSubPanel(0, hh, hw, height - hh, {
      title: "(c) Refractive Index n(ω) & Extinction k(ω)",
      yMinForced: 0,
      series: [
        { label: "n(ω)", values: spec.nArr, color: "#16a34a", width: 2.0 },
        { label: "k(ω)", values: spec.kArr, color: "#ea580c", width: 2.0, dashed: true }
      ]
    });
    drawOpticalSubPanel(hw, hh, width - hw, height - hh, {
      title: "(d) Reflectivity R(ω) & Energy Loss L(ω)",
      yMinForced: 0,
      series: [
        { label: "Reflectivity R(ω)", values: spec.reflArr, color: "#7c3aed", width: 2.0 },
        { label: "EELS Loss L(ω)", values: spec.lossArr, color: "#be123c", width: 2.0, fillAlpha: "rgba(190,18,60,0.08)" }
      ]
    });
  } else if (prop === "absorption") {
    drawOpticalSubPanel(0, 0, width, height, {
      title: `CASTEP Optical Absorption Coefficient α(ω) (×10⁴ cm⁻¹) — ${job.seed || CASTEP_STUDIO_STATE.structure.formula}`,
      yMinForced: 0,
      series: [
        { label: "Absorption α(ω) (×10⁴ cm⁻¹)", values: alpha10k, color: "#0284c7", width: 2.4, fillAlpha: "rgba(2,132,199,0.14)" }
      ]
    });
  } else if (prop === "dielectric") {
    drawOpticalSubPanel(0, 0, width, height, {
      title: `CASTEP Complex Dielectric Function ε₁(ω) & ε₂(ω) — ${job.seed || CASTEP_STUDIO_STATE.structure.formula}`,
      series: [
        { label: "ε₁(ω) dispersive (Real)", values: spec.eps1, color: "#2563eb", width: 2.3 },
        { label: "ε₂(ω) absorptive (Imaginary)", values: spec.eps2, color: "#dc2626", width: 2.3, fillAlpha: "rgba(220,38,38,0.10)" }
      ]
    });
  } else if (prop === "refractive") {
    drawOpticalSubPanel(0, 0, width, height, {
      title: `CASTEP Complex Refractive Index n(ω) & Extinction Coefficient k(ω) — ${job.seed || CASTEP_STUDIO_STATE.structure.formula}`,
      yMinForced: 0,
      series: [
        { label: "Refractive Index n(ω)", values: spec.nArr, color: "#16a34a", width: 2.3 },
        { label: "Extinction Coefficient k(ω)", values: spec.kArr, color: "#ea580c", width: 2.3, fillAlpha: "rgba(234,88,12,0.10)" }
      ]
    });
  } else if (prop === "reflectivity") {
    drawOpticalSubPanel(0, 0, width, height, {
      title: `CASTEP Optical Reflectivity R(ω) — ${job.seed || CASTEP_STUDIO_STATE.structure.formula}`,
      yMinForced: 0,
      series: [
        { label: "Reflectivity R(ω)", values: spec.reflArr, color: "#7c3aed", width: 2.4, fillAlpha: "rgba(124,58,237,0.12)" }
      ]
    });
  } else if (prop === "conductivity") {
    drawOpticalSubPanel(0, 0, width, height, {
      title: `CASTEP Optical Conductivity σ₁(ω) & σ₂(ω) (1/fs) — ${job.seed || CASTEP_STUDIO_STATE.structure.formula}`,
      series: [
        { label: "Re[σ(ω)] (1/fs)", values: spec.cond1Arr, color: "#0f766e", width: 2.3, fillAlpha: "rgba(15,118,110,0.12)" },
        { label: "Im[σ(ω)] (1/fs)", values: spec.cond2Arr, color: "#b45309", width: 2.0, dashed: true }
      ]
    });
  } else if (prop === "loss") {
    drawOpticalSubPanel(0, 0, width, height, {
      title: `CASTEP Electron Energy Loss Spectrum (EELS) L(ω) = Im[-1/ε(ω)] — ${job.seed || CASTEP_STUDIO_STATE.structure.formula}`,
      yMinForced: 0,
      series: [
        { label: "Energy Loss Function L(ω)", values: spec.lossArr, color: "#be123c", width: 2.4, fillAlpha: "rgba(190,18,60,0.14)" }
      ]
    });
  } else if (prop === "tauc") {
    drawOpticalSubPanel(0, 0, width, height, {
      title: `Tauc Plot Optical Band Gap Analysis (E_g^opt ≈ ${spec.metrics.optGapEv.toFixed(2)} eV) — ${job.seed || CASTEP_STUDIO_STATE.structure.formula}`,
      yMinForced: 0,
      series: [
        { label: "Direct (αħω)² (arb. u.)", values: spec.taucDirArr, color: "#2563eb", width: 2.3 },
        { label: "Indirect (αħω)¹/² (arb. u.)", values: spec.taucIndArr, color: "#16a34a", width: 2.1, dashed: true }
      ]
    });
  }

  ctx.restore();
}
window.renderCastepOpticalPlots = renderCastepOpticalPlots;

function initCastepOpticsCanvasHover() {
  const canvas = document.getElementById("castep-optics-canvas");
  if (!canvas || canvas._opticsHoverBound) return;
  canvas._opticsHoverBound = true;
  canvas.addEventListener("mousemove", (e) => {
    const readout = document.getElementById("castep-optics-readout");
    const spec = CASTEP_STUDIO_STATE.lastOpticalSpectra;
    if (!readout || !spec || !spec.hwGrid.length) return;
    const rect = canvas.getBoundingClientRect();
    const mx = e.clientX - rect.left;
    const prop = document.getElementById("castep-opt-property")?.value || "multigrid";
    const hwPanelW = prop === "multigrid" ? (rect.width / 2) : rect.width;
    const localX = prop === "multigrid" ? (mx % hwPanelW) : mx;
    const padL = 58, padR = 16;
    const pw = hwPanelW - padL - padR;
    const frac = Math.max(0, Math.min(1, (localX - padL) / (pw || 1)));
    const idx = Math.min(spec.hwGrid.length - 1, Math.max(0, Math.round(frac * (spec.hwGrid.length - 1))));
    const hw = spec.hwGrid[idx];
    const lam = 1239.84 / Math.max(0.05, hw);
    readout.innerHTML =
      `Cursor: <strong>ħω = ${hw.toFixed(2)} eV</strong> (λ = <strong>${Math.round(lam)} nm</strong>) • ` +
      `ε₁ = <strong>${spec.eps1[idx].toFixed(2)}</strong>, ε₂ = <strong>${spec.eps2[idx].toFixed(2)}</strong> • ` +
      `α = <strong>${Math.round(spec.alphaCm[idx]).toLocaleString()} cm⁻¹</strong> • ` +
      `n = <strong>${spec.nArr[idx].toFixed(2)}</strong>, k = <strong>${spec.kArr[idx].toFixed(2)}</strong> • ` +
      `R = <strong>${(spec.reflArr[idx] * 100).toFixed(1)}%</strong>, L = <strong>${spec.lossArr[idx].toFixed(3)}</strong>`;
  });
}

function exportCastepOpticalCSV() {
  const job = (CASTEP_STUDIO_STATE.jobs || []).find(j => j.id === CASTEP_STUDIO_STATE.activeJobId) || {};
  const spec = CASTEP_STUDIO_STATE.lastOpticalSpectra || computeCastepOpticalSpectra(job);
  let csv = "Energy_eV,Wavelength_nm,Eps1_Real,Eps2_Imag,Absorption_cm-1,Refractive_n,Extinction_k,Reflectivity_R,Conductivity_Re_1_fs,Loss_Function_L\n";
  for (let i = 0; i < spec.hwGrid.length; i++) {
    const hw = spec.hwGrid[i];
    const nm = 1239.84193 / Math.max(0.01, hw);
    csv += `${hw.toFixed(4)},${nm.toFixed(2)},${spec.eps1[i].toFixed(5)},${spec.eps2[i].toFixed(5)},${spec.alphaCm[i].toFixed(2)},${spec.nArr[i].toFixed(5)},${spec.kArr[i].toFixed(5)},${spec.reflArr[i].toFixed(5)},${spec.cond1Arr[i].toFixed(5)},${spec.lossArr[i].toFixed(5)}\n`;
  }
  const blob = new Blob([csv], { type: "text/csv;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `${job.seed || "CASTEP"}_Optical_Properties.csv`;
  document.body.appendChild(a);
  a.click();
  setTimeout(() => { a.remove(); URL.revokeObjectURL(url); }, 200);
  if (typeof showToast === "function") showToast("Exported CASTEP Optical Properties CSV!", "success");
}
window.exportCastepOpticalCSV = exportCastepOpticalCSV;

